/** Validates input against the tool's inputSchema; see specs/hal-engine-tool-input-validation/spec.md. */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }
  const definition = this.resolveDefinition(tool.definitionSource);
  const validate = ajv.compile(definition.inputSchema);
  if (!validate(input)) {
    const errors = validate.errors ?? [];
    const rejectionMessage = errors
      .map(error => {
        if (error.keyword === 'required') {
          const params = error.params as {missingProperty: string};
          return params.missingProperty.replace(/^\./, '') + ': required';
        }
        return `${error.dataPath || '.'}: ${error.message ?? 'invalid'}`;
      })
      .join('; ');
    log.warn('tool', 'input validation failed', {name, errorCount: errors.length});
    return {result: `Input validation failed: ${rejectionMessage}`};
  }
  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});

